# ── Enums ─────────────────────────────────────────────────────────────────────

class Status(enum.Enum):
    PENDING   = "pending"
    RUNNING   = "running"
    SUCCESS   = "success"
    FAILED    = "failed"
    CANCELLED = "cancelled"

@runtime_checkable
class HasStatus(Protocol[K]):
    status: K


@dataclasses.dataclass(frozen=True)
class Job(Generic[T], HasStatus[Status]):  # type: ignore[misc]
    """Job class with properties."""

    result: T | None
    status: Status
    id: int = 0
    description: str = ""

    @property
    def is_succeeded(self) -> bool:
        return self.status == Status.SUCCESS

    @property
    def is_failed(self) -> bool:
        return self.status == Status.FAILED

    @property
    def is_cancelled(self) -> bool:
        return self.status == Status.CANCELLED


